# region: render
def render(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: digest
def digest(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: fold
def fold(xs):
    return [v for v in xs if v % 2 == 0]

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: gather
def gather(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return gather(emit(fold(digest(render(raw)))))

